package skillregistry

import (
	"errors"
	"strings"
	"testing"
)

const wantHead = "# Skill Registry — proj\n" +
	"\n" +
	"<!-- Auto-generated by labdrian skill-registry refresh. Run `labdrian skill-registry refresh --force` to regenerate. -->\n" +
	"\n" +
	"Last updated: 2026-11-18\n" +
	"\n" +
	"## Sources scanned\n" +
	"\n" +
	"- skills\n" +
	"- /h/.claude/skills\n" +
	"\n" +
	"## Contract\n" +
	"\n" +
	"**Delegator use only.** This registry is an index, not a summary. Any agent that launches subagents reads it to select relevant skills, then passes exact `SKILL.md` paths for the subagent to read before work.\n" +
	"\n" +
	"`SKILL.md` remains the source of truth. Do not inject generated summaries or compact rules by default; pass paths so subagents load the full runtime contract and preserve author intent.\n" +
	"\n"

const tableHead = "## Skills\n" +
	"\n" +
	"| Skill | Trigger / description | Scope | Path |\n" +
	"| --- | --- | --- | --- |\n"

const wantProtocol = "## Loading protocol\n" +
	"\n" +
	"1. Match task context and target files against the `Trigger / description` column.\n" +
	"2. Pass only the matching `Path` values to the subagent under `## Skills to load before work`.\n" +
	"3. Instruct the subagent to read those exact `SKILL.md` files before reading, writing, reviewing, testing, or creating artifacts.\n" +
	"4. If no matching skill exists, proceed without project skill injection and report `skill_resolution: none`.\n"

var testHeader = Header{Project: "proj", Sources: []string{"skills", "/h/.claude/skills"}, Date: "2026-11-18"}

var testRows = []Row{
	{"alpha", "first", ScopeProject, "/p/skills/alpha/SKILL.md"},
	{"beta", "second", ScopeUser, "/h/.claude/skills/beta/SKILL.md"},
}

const testRowLines = "| `alpha` | first | project | `/p/skills/alpha/SKILL.md` |\n" +
	"| `beta` | second | user | `/h/.claude/skills/beta/SKILL.md` |\n"

func compose(t *testing.T, existing string, h Header, rows []Row) string {
	t.Helper()
	got, err := Compose(existing, h, rows)
	if err != nil {
		t.Fatalf("Compose: %v", err)
	}
	return got
}

func TestComposeWritesTheRegistryOfAProjectThatHasNone(t *testing.T) {
	got := compose(t, "", testHeader, testRows)
	want := wantHead + tableHead + testRowLines + "\n" + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeWritesAnEmptyTableWhenThereAreNoSkills(t *testing.T) {
	got := compose(t, "", testHeader, nil)
	want := wantHead + tableHead + "\n" + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeRegeneratesTheHeaderAndTheRowsOfTheRegistryOfGentle(t *testing.T) {
	gentle := strings.NewReplacer(
		"labdrian skill-registry refresh", "gentle-ai skill-registry refresh",
		"Last updated: 2026-11-18", "Last updated: 2026-11-01",
		"- /h/.claude/skills\n", "- /h/.old/skills\n",
		"# Skill Registry — proj", "# Skill Registry — oldname",
	).Replace(wantHead + tableHead + "| `stale` | row | user | `/x` |\n" + "\n" + wantProtocol)
	got := compose(t, gentle, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + "\n" + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeIsIdempotent(t *testing.T) {
	once := compose(t, "", testHeader, testRows)
	twice := compose(t, once, testHeader, testRows)
	if once != twice {
		t.Fatalf("second compose changed the registry:\n%s\nvs\n%s", once, twice)
	}
}

func TestComposeKeepsTheExecutorNoteAboveTheSkillsHeading(t *testing.T) {
	const note = "`sdd-*` phase skills are executor contracts. Gentle may skip them as user-invocable skills, but this registry keeps their paths visible so SDD delegation can resolve the existing installed files.\n"
	existing := strings.Replace(wantHead+tableHead+"\n"+wantProtocol, tableHead, note+"\n"+tableHead, 1)
	got := compose(t, existing, testHeader, testRows)
	want := wantHead + note + "\n" + tableHead + testRowLines + "\n" + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeKeepsTheExecutorRowsAfterTheBlankLine(t *testing.T) {
	const executors = "| `sdd-apply` | Apply | executor | `/h/.codex/skills/sdd-apply/SKILL.md` |\n" +
		"| `sdd-verify` | Verify | executor | `/h/.codex/skills/sdd-verify/SKILL.md` |\n"
	existing := wantHead + tableHead + "| `stale` | row | user | `/x` |\n" + "\n" + executors + "\n" + wantProtocol
	got := compose(t, existing, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + "\n" + executors + "\n" + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeKeepsExecutorRowsThatTouchTheTable(t *testing.T) {
	const executor = "| `sdd-apply` | Apply | executor | `/e` |\n"
	existing := wantHead + tableHead + "| `stale` | row | user | `/x` |\n" + executor + "\n" + wantProtocol
	got := compose(t, existing, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + executor + "\n" + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

// A table that is not the generator's, written right under its rows with no blank line between, is
// not eaten: only the rows of the skills the generator writes are replaced.
func TestComposeKeepsAForeignRowRightUnderTheTable(t *testing.T) {
	const foreign = "| Contract | Path |\n| --- | --- |\n| minimalism | skills/_shared/minimalism-contract.md |\n"
	existing := wantHead + tableHead + "| `stale` | row | user | `/x` |\n" + foreign + "\n" + wantProtocol
	got := compose(t, existing, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + foreign + "\n" + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

// A refresh after a repair is a no-op when nothing else changed: the blank lines the repair leaves
// in the head, above the executor note, are the registry's own and stay as they are.
func TestComposeKeepsTheBlankLinesOfTheHeadByteForByte(t *testing.T) {
	const note = "`sdd-*` phase skills are executor contracts. Gentle may skip them as user-invocable skills, but this registry keeps their paths visible so SDD delegation can resolve the existing installed files.\n"
	existing := wantHead + "\n" + note + "\n" + tableHead + testRowLines + "\n" + wantProtocol
	if got := compose(t, existing, testHeader, testRows); got != existing {
		t.Fatalf("registry changed:\n%s\nwant\n%s", got, existing)
	}
}

func TestComposeKeepsTheHermesSectionByteForByte(t *testing.T) {
	const hermes = "<!-- labdrian-hermes sha256=0123abcd root=ffee -->\n" +
		"| `hermes-skill` | Hermes | user | `/h/.hermes/skills/x/SKILL.md` |\n" +
		"<!-- /labdrian-hermes -->\n"
	existing := wantHead + tableHead + "| `stale` | row | user | `/x` |\n" + "\n" + hermes + wantProtocol
	got := compose(t, existing, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + "\n" + hermes + wantProtocol
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeKeepsTheLoadingProtocolAsItIs(t *testing.T) {
	custom := "## Loading protocol\n\n1. Owner's own protocol.\n\twith a tab, and no final newline"
	existing := wantHead + tableHead + "\n" + custom
	got := compose(t, existing, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + "\n" + custom
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeKeepsThePropagateBlocksByteForByte(t *testing.T) {
	const blocks = "\n<!-- BEGIN: minimalism-contract-scope (auto-generated) -->\n" +
		"| minimalism-contract | skills/_shared/minimalism-contract.md | Inject ONLY into shaper |\n" +
		"<!-- END: minimalism-contract-scope -->\n" +
		"\n<!-- BEGIN: anti-generic-design-scope (auto-generated) -->\n" +
		"| anti-generic-design | skills/_shared/anti-generic-design.md | Inject ONLY into builder |\n" +
		"<!-- END: anti-generic-design-scope -->\n"
	existing := wantHead + tableHead + "| `stale` | row | user | `/x` |\n" + "\n" + wantProtocol + blocks
	got := compose(t, existing, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + "\n" + wantProtocol + blocks
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeKeepsALineAboveTheTitleAndAnUnknownLineInTheHead(t *testing.T) {
	existing := "<!-- owner note -->\n" + wantHead + "An owner paragraph.\n\n" + tableHead + "\n" + wantProtocol
	got := compose(t, existing, testHeader, testRows)
	if !strings.Contains(got, "<!-- owner note -->\n") || !strings.Contains(got, "An owner paragraph.\n\n"+tableHead) {
		t.Fatalf("an owner line was lost:\n%s", got)
	}
	if strings.Count(got, "# Skill Registry") != 1 || strings.Count(got, "Last updated:") != 1 {
		t.Fatalf("the header was written twice:\n%s", got)
	}
}

func TestComposeStartsFromARegistryThatHasOnlyTheHeadings(t *testing.T) {
	minimal := "# Skill Registry — proj\n\n## Skills\n\n| Skill | Trigger / description | Scope | Path |\n| --- | --- | --- | --- |\n\n## Loading protocol\n\n1. a\n2. b\n"
	got := compose(t, minimal, testHeader, testRows)
	want := wantHead + tableHead + testRowLines + "\n" + "## Loading protocol\n\n1. a\n2. b\n"
	if got != want {
		t.Fatalf("registry =\n%s\nwant\n%s", got, want)
	}
}

func TestComposeRefusesARegistryWithoutItsSkillsTable(t *testing.T) {
	for name, existing := range map[string]string{
		"no skills heading": "# Skill Registry — proj\n\n" + wantProtocol,
		"no table":          "# Skill Registry — proj\n\n## Skills\n\nsome words\n\n" + wantProtocol,
		"no separator":      "## Skills\n\n| Skill | Trigger / description | Scope | Path |\nnot a separator\n",
	} {
		t.Run(name, func(t *testing.T) {
			got, err := Compose(existing, testHeader, testRows)
			var unrecognized *UnrecognizedError
			if !errors.As(err, &unrecognized) {
				t.Fatalf("err = %v, want *UnrecognizedError (got %q)", err, got)
			}
			if got != "" {
				t.Fatalf("a refused registry returned text %q", got)
			}
		})
	}
}

func TestLastUpdatedIsTheDateTheRegistrySays(t *testing.T) {
	if got := LastUpdated(wantHead + tableHead); got != "2026-11-18" {
		t.Fatalf("LastUpdated = %q", got)
	}
	if got := LastUpdated("# Skill Registry — proj\n"); got != "" {
		t.Fatalf("LastUpdated of a registry with no date = %q", got)
	}
}
